import { indexAnnotations, NONE_DECLARED, readable, type Annotation, type Declared, type Resolved } from "../annotations.ts";
import { parseSeries } from "../attributes.ts";
import { onFaceChange, onFontsLoaded } from "../face.ts";
import { resolvePalette, type Palette } from "../palette.ts";
import type { Colour } from "../roles.ts";
import { absolute, annotationsFor, annotationsFromText, bundledIn, infoFor, sourceFor } from "../registry.ts";
import type { RecordingInfo, Source } from "../source.ts";
import { HOST_TEXT } from "./summary-style.ts";

export const SHARED_CSS = `
:host { display: block; ${HOST_TEXT} }
:host([hidden]) { display: none; }
/* Important, because a page's ::part() rule giving a part its display otherwise beats this one. */
[hidden] { display: none !important; }
.probe { display: none; }
button, select { font: inherit; font-size: 13px; line-height: 1.2; color: var(--ink, CanvasText); background: transparent;
  border: 1px solid var(--rule, GrayText); border-radius: 6px; padding: 3px 9px; min-height: 26px; cursor: pointer; }
select { padding-right: 4px; background: var(--raised, Canvas); }
button:hover, select:hover { background: var(--wash, color-mix(in srgb, CanvasText 12%, transparent)); }
button:disabled { opacity: .45; cursor: default; background: transparent; }
:focus-visible { outline: var(--focus-width, 2px) solid var(--ink, CanvasText); outline-offset: 2px; }
.notice { margin: 4px 0 0; padding: 1px 8px; font-size: 12px; line-height: 1.4; color: var(--attention-ink, CanvasText);
  border-left: 2px solid var(--attention-ink, CanvasText); }
.figures { font-family: var(--font-figures, ui-monospace, monospace); font-stretch: var(--figures-stretch, normal);
  font-weight: var(--figures-weight, 500); font-variant-numeric: tabular-nums; font-size: 12px; }
`;

/** A press that moves this far, in CSS pixels, is a drag rather than a click. */
export const DRAG_PX = 4;

/** The key that turns the wheel into a zoom: Cmd on Apple's systems, Ctrl elsewhere. */
export function zoomKey(): "Cmd" | "Ctrl" {
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  return /mac|iphone|ipad/i.test(nav.userAgentData?.platform || navigator.platform) ? "Cmd" : "Ctrl";
}

export interface Loaded {
  readonly src: URL;
  readonly source: Source;
  readonly info: RecordingInfo;
  readonly annotations: Resolved;
}

/**
 * The recording at `src` and its annotations, shared with every element on the page. Without an
 * `annotations` URL, a bundled sidecar serves. A sidecar's problems are in `annotations.errors`;
 * the recording still draws.
 */
export async function loadRecording(src: string, annotations: string | null, text: string | null = null): Promise<Loaded> {
  const head = await loadHead(src);
  return { ...head, annotations: await loadAnnotations(head.src, annotations, text) };
}

/** The recording at `src` without its annotations: what a first draw needs. */
export async function loadHead(src: string): Promise<Omit<Loaded, "annotations">> {
  const url = absolute(src);
  const [source, info] = await Promise.all([sourceFor(url), infoFor(url)]);
  return { src: url, source, info };
}

/**
 * The recording's sidecar: the hand-written file's `text` when given, with its includes beside
 * `annotations`; else the file at `annotations`; else the bundled one, as far as it is read: those
 * of its annotations ticks `span` meet, with any read before, or every one where `span` is null.
 * Problems are in `errors`, and so is each annotation left out for naming a channel this version
 * can't read; what a later minor version holds that this reader leaves out is in `notes`.
 */
export async function loadAnnotations(recording: URL, annotations: string | null, text: string | null, span: readonly [number, number] | null = null): Promise<Resolved> {
  try {
    return await readAnnotations(recording, annotations, text, span);
  } catch (e) {
    return indexAnnotations([], [e instanceof Error ? e.message : String(e)]);
  }
}

/** As `loadAnnotations`, rejecting where they don't read: a read of more of a bundled sidecar
 * that fails leaves what was read before. */
export async function readAnnotations(recording: URL, annotations: string | null, text: string | null, span: readonly [number, number] | null): Promise<Resolved> {
  let list: Annotation[];
  let declared: Declared = NONE_DECLARED;
  const errors: string[] = [];
  let notes: readonly string[] = [];
  let partial = false;
  const at = annotations ? absolute(annotations) : null;
  if (text !== null || at) {
    const sidecar = text !== null ? await annotationsFromText(text, at, recording) : await annotationsFor(at!, recording);
    list = sidecar.annotations;
    declared = sidecar;
    notes = sidecar.notes ?? [];
  } else {
    const read = await bundledIn(recording, span);
    list = read?.annotations ?? [];
    declared = read?.declared ?? NONE_DECLARED;
    errors.push(...(read?.problems ?? []));
    notes = read?.notes ?? [];
    partial = read !== null && !read.complete;
  }
  list = readable(list, (await infoFor(recording)).channels, errors);
  return indexAnnotations(list, errors, partial, { roles: declared.roles, view: declared.view }, notes);
}

export abstract class TickwaveElement extends HTMLElement {
  protected readonly root: ShadowRoot;
  readonly #probe: HTMLSpanElement;
  protected palette: Palette | null = null;
  #unsubscribe: (() => void)[] = [];
  #queued = false;
  #reportedErrors = new Set<string>();
  #notes = new Set<string>();
  #waiting: string | null = null;

  constructor(css: string, html: string) {
    super();
    this.root = this.attachShadow({ mode: "open" });
    this.root.innerHTML = `<style>${SHARED_CSS}${css}</style><span class="probe" aria-hidden="true"></span>${html}`;
    this.#probe = this.root.querySelector(".probe")!;
  }

  connectedCallback(): void {
    if (this.drawsWithPalette) {
      this.#unsubscribe.push(
        onFaceChange(() => this.faceTurned()),
        onFontsLoaded(() => this.fontsChanged()),
      );
    }
    this.refreshPalette();
    this.queueUpdate();
  }

  /** Whether the element draws in the page's colours. One that only holds text, as a reference
   * does, reads none of them: a page of fifty references costs nothing on a face change. */
  protected get drawsWithPalette(): boolean {
    return true;
  }

  disconnectedCallback(): void {
    for (const u of this.#unsubscribe.splice(0)) u();
  }

  attributeChangedCallback(name: string, old: string | null, value: string | null): void {
    if (old === value) return;
    if (name === "series") this.refreshPalette();
    this.queueUpdate();
  }

  /** Coalesces attribute changes made together into one update. */
  protected queueUpdate(): void {
    if (this.#queued) return;
    this.#queued = true;
    queueMicrotask(() => {
      this.#queued = false;
      if (this.isConnected) this.update();
    });
  }

  protected abstract update(): void;

  /** The series name, from this element or the one it borrows a recording from. */
  protected get series(): string | null {
    return parseSeries(this.getAttribute("series"));
  }

  /** The trace colour the recording stores (ANNOTATIONS.md, "The stored view"), under the
   * page's: an element that has read its sidecar gives it. */
  protected get storedColour(): Colour | null {
    return null;
  }

  /** The stored colour last read, so the palette is read again only when it changes. */
  #stored: Colour | null = null;

  protected refreshPalette(): void {
    if (!this.isConnected || !this.drawsWithPalette) return;
    this.#stored = this.storedColour;
    this.palette = resolvePalette(this.#probe, this.series, this.#stored);
    this.paletteChanged();
  }

  /** Reads the palette again where the stored colour changed: a sidecar that arrived, or another. */
  protected storedColourChanged(): void {
    const c = this.storedColour;
    if (c?.day === this.#stored?.day && c?.night === this.#stored?.night) return;
    this.refreshPalette();
  }

  protected abstract paletteChanged(): void;

  /** The page's face has turned (face.ts): the colours are read again. */
  protected faceTurned(): void {
    this.refreshPalette();
  }

  protected fontsChanged(): void {
    this.paletteChanged();
  }

  /**
   * Reports a problem once: as `tickwave-error`, in the console, and in a short notice in the
   * element, so a page's author sees it. The element goes on with what it has.
   */
  protected fail(e: unknown): void {
    const message = e instanceof Error ? e.message : String(e);
    if (this.#reportedErrors.has(message)) return;
    this.#reportedErrors.add(message);
    console.warn(`<${this.localName}${this.id ? ` id="${this.id}"` : ""}>: ${message}`);
    this.dispatchEvent(new CustomEvent("tickwave-error", { detail: { message, error: e }, bubbles: true, composed: true }));
    this.#showNotice();
  }

  /** Says something the reader should know that is not a problem, once: in the console, and in the
   * notice where no problem is. */
  protected note(message: string): void {
    if (this.#notes.has(message)) return;
    this.#notes.add(message);
    console.info(`<${this.localName}${this.id ? ` id="${this.id}"` : ""}>: ${message}`);
    this.#showNotice();
  }

  /** Forgets the problems and notes reported so far: a notice is about the recording or sidecar it
   * came from, and a new one starts without it. */
  protected clearProblems(): void {
    this.#reportedErrors.clear();
    this.#notes.clear();
    this.#showNotice();
  }

  /** Forgets one problem, once what it was about has gone. */
  protected forgetProblem(message: string): void {
    if (this.#reportedErrors.delete(message)) this.#showNotice();
  }

  /** As `forgetProblem`, for a note. */
  protected forgetNote(message: string): void {
    if (this.#notes.delete(message)) this.#showNotice();
  }

  /** Says a read has run `ms` and is still going, or with null that none is. A problem or a note
   * comes first. */
  protected waiting(ms: number | null): void {
    this.#waiting = ms === null ? null : `Still loading after ${ms / 1000} s.`;
    this.#showNotice();
  }

  #showNotice(): void {
    const notice = this.root.querySelector(".notice") as HTMLElement | null;
    if (!notice) return;
    const problems = [...this.#reportedErrors].flatMap((m) => m.split("\n")).filter(Boolean);
    const shown = problems.length > 0 ? problems : [...this.#notes];
    const word = problems.length > 0 ? "problem" : "note";
    notice.hidden = shown.length === 0 && this.#waiting === null;
    notice.textContent =
      shown.length === 0
        ? (this.#waiting ?? "")
        : shown.length === 1
          ? shown[0]
          : `${shown[0]} (and ${shown.length - 1} more ${shown.length === 2 ? word : `${word}s`}; see the console)`;
  }

  protected emit(name: string, detail: unknown): void {
    this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }));
  }
}
